// Every draft is checked by code. A failed check keeps the draft but marks it, so a person sees why.
const briefs = $('Build briefs').all().map((i) => i.json);
const input = $('Run input').first().json;
const parse = (item) => {
  if (!item || item.error) return { error: 'AI call failed after retries' };
  const text = (item.content || []).filter((b) => b.type === 'text').map((b) => b.text).join('\n').replace(/```json|```/g, '').trim();
  try { return JSON.parse(text); } catch (e) { return { error: 'AI result is not valid JSON' }; }
};
const results = $input.all().map((i) => i.json);
const byAlert = {};
briefs.forEach((b, i) => {
  const r = parse(results[i]);
  const row = byAlert[b.alert_id] || (byAlert[b.alert_id] = { id: b.alert_id, site_id: b.site_id, client_name: b.client_name, level: b.level,
    csm_alert: '', email_subject: '', email_body: '', flags: [], is_canary: false });
  if (r.error) { row.flags.push('NO DRAFT (' + b.kind + '): ' + r.error); return; }
  if (b.kind === 'csm_alert') {
    row.csm_alert = String(r.text || '').trim();
    checkCsmAlert(row.csm_alert, b).forEach((f) => row.flags.push('CSM alert: ' + f));
  } else {
    const subject = String(r.subject || '').trim();
    const body = String(r.body || '').trim();
    checkEmail(subject, body, b.vendor_names, b.topic).forEach((f) => row.flags.push('Client email: ' + f));
    row.email_subject = subject.split('[CLIENT]').join(b.client_name);
    row.email_body = body.split('[CLIENT]').join(b.client_name);
  }
});
const rows = Object.values(byAlert).map((r) => ({ json: { ...r, check_passed: r.flags.length === 0,
  check_notes: r.flags.length ? r.flags.join(' | ') : 'All checks passed', review_status: 'pending review' } }));

// Test only: hand-written emails that the checks must catch (or, for the good one, must let through).
const vendorNames = [...new Set($('Get signatures').all().map((i) => i.json).filter((s) => s.vendor && s.is_ours !== true).map((s) => s.vendor))];
input.canaries.forEach((c) => {
  const flags = checkEmail(c.subject, c.body, vendorNames, c.topic);
  const actual = flags.length ? 'flagged' : 'passes';
  rows.push({ json: { is_canary: true, run_id: input.run_id, run_at: $now.setZone('Europe/Warsaw').toFormat('yyyy-MM-dd HH:mm'),
    suite: 'draft-checker', case_id: c.id, site_id: '', day: 0, expected: c.expect, actual, passed: actual === c.expect,
    outcome: actual === c.expect ? 'ok' : (c.expect === 'flagged' ? 'missed' : 'false alarm'),
    detail: (c.what + ' -> ' + (flags.length ? flags.join(' | ') : 'All checks passed')).slice(0, 400) } });
});
return rows;
